function registryOutputsModelInput({key='',prevKey='',policy='',mint='',prevPayment='',prevStake='none',prevRef='none',prevAssets='',newPayment='',newStake='none',newRef='none',newAssets=''}={}){
  const parseMint=text=>(text??'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(line=>{
    const parts=line.split(/\s+/).filter(Boolean);
    if(parts.length!==2)throw new Error(`Each mint line must name an asset name and a quantity — ${JSON.stringify(line)} given. Use a dash for the empty name.`);
    return {name:parts[0]==='-'?'':parts[0],quantity:parts[1]};
  });
  const parseAssets=text=>(text??'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(line=>{
    const parts=line.split(/\s+/).filter(Boolean);
    if(parts.length!==3)throw new Error(`Each asset line must name a policy, an asset name, and a quantity — ${JSON.stringify(line)} given. Use a dash for the empty name.`);
    return {policy:parts[0],name:parts[1]==='-'?'':parts[1],quantity:parts[2]};
  });
  const output=(payment,stake,ref,assets)=>({paymentHash:(payment??'').trim(),stakeCredential:stake==='present',referenceScript:ref==='present',assets:parseAssets(assets)});
  return {key:String(key??'').trim(),prevKey:String(prevKey??'').trim(),registryPolicy:String(policy??'').trim(),minted:parseMint(mint),prevOutput:output(prevPayment,prevStake,prevRef,prevAssets),newOutput:output(newPayment,newStake,newRef,newAssets)};
}
