    const chain=r.chainOrdered?`<p class="fine-print"><strong>Chain order · MEETS THE SPEC</strong> — next (${nextShow}) sorts strictly after key (${keyShow}) under bytestring comparison, as a linked-list node must.</p>`:`<p class="fine-print"><strong>Chain order · DOES NOT MEET THE SPEC</strong> — next (${nextShow}) does not sort strictly after key (${keyShow}): a node's next names the FOLLOWING key in lexicographic order, and a node pointing at or behind itself links nothing.</p>`;
    const unf=r.unfrackingMode==='forbidden'?`<p class="fine-print"><strong>Unfracking · FORBIDDEN for this policy</strong> — the empty public-key credential is the least-permission default: no unfracking script exists for this token, so no unfracking transaction can invoke one.</p>`:r.unfrackingMode==='signature-gated'?`<p class="fine-print"><strong>Unfracking · SIGNATURE-GATED</strong> — a public-key credential: an unfracking action must invoke this credential's withdraw-zero, and a withdrawal against a public-key reward account requires that key's signature.</p>`:r.unfrackingMode==='script-delegated'?`<p class="fine-print"><strong>Unfracking · DELEGATED TO A SCRIPT</strong> — a script credential: an unfracking action must invoke that hook validator's withdraw-zero, and the hook decides.</p>`:`<p class="fine-print"><strong>Unfracking · NOT READ</strong> — the unfracking credential breaks its field rule above, so no mode can be read from it.</p>`;
