function globalDispatchDiffPreview(input={}){
  const afterD=String(input.afterDelegatesText??'').trim(),afterW=String(input.afterWithdrawalsText??'').trim();
  if(!afterD&&!afterW)return `<p class="fine-print">Enter the dispatch as it would be after the change \u2014 its delegate wiring and its withdrawals \u2014 and how the dispatch checked above changes appears as you type, compared locally between the two versions. The declared action is taken from the checker above.</p>`;
  try{
    const action=input.action??'transfer';
    const before=globalDispatchModelInput({action,delegatesText:input.delegatesText??'',withdrawalsText:input.withdrawalsText??''});
    const after=globalDispatchModelInput({action,delegatesText:input.afterDelegatesText??'',withdrawalsText:input.afterWithdrawalsText??''});
    const d=diffGlobalDispatch(before,after);
    const cred=c=>`${esc(c.kind)} <span class="mono">${esc(c.hash.slice(0,8))}\u2026</span>`;
    const labels={'unchanged':['DISPATCH UNCHANGED','the change leaves the dispatch exactly as checked above \u2014 the same delegate is required, and it is invoked, or not, in both versions'],'became-not-conforming':['BECAME NOT CONFORMING','the after version no longer invokes the delegate the wiring names for the declared action, so the dispatcher would refuse a spend the before version\u2019s dispatch allowed'],'became-conforming':['BECAME CONFORMING','the before version did not invoke the required delegate and the after version does \u2014 the dispatcher\u2019s one requirement is now met'],'still-not-conforming':['STILL NOT CONFORMING \u2014 DIFFERENTLY','neither version invokes its required delegate, but the required delegate itself changed, so restoring the before version\u2019s withdrawal does not restore the same dispatch'],'requirement-changed':['REQUIREMENT CHANGED','the dispatch conforms on both sides, but the delegate the wiring requires is a different credential \u2014 what validates the declared action is no longer what validated it before']};
    const pair=labels[d.change];
    const showVal=(field,v)=>field==='status'?(v==='conforming'?'conforming':'not conforming'):field==='delegateInvoked'?(v?'invoked':'not invoked'):null;
    const lines=d.differences.map(x=>`<p class="fine-print"><strong>${esc(x.label)} · DIFFERS</strong> \u2014 before: ${x.field==='delegate'?cred(x.before):esc(showVal(x.field,x.before))}; after: ${x.field==='delegate'?cred(x.after):esc(showVal(x.field,x.after))}.</p>`).join('');
    const listLines=[
      d.wiringChangedFields.length?`<p class="fine-print"><strong>Delegate wiring re-pointed</strong> \u2014 ${d.wiringChangedFields.map(esc).join(', ')}. Re-pointing a delegate for an action this dispatch does not declare moves no position above: this dispatch\u2019s requirement reads only its own action\u2019s field.</p>`:'',
      d.addedWithdrawals.length?`<p class="fine-print"><strong>Withdrawals added</strong> \u2014 ${d.addedWithdrawals.map(cred).join(', ')}.</p>`:'',
      d.removedWithdrawals.length?`<p class="fine-print"><strong>Withdrawals removed</strong> \u2014 ${d.removedWithdrawals.map(cred).join(', ')}.</p>`:'',
      d.otherDelegatesChanged?`<p class="fine-print"><strong>Another delegate\u2019s invocation changed</strong> \u2014 reported, never counted: the standard requires the declared action\u2019s delegate and states no prohibition on another also being invoked, so another delegate\u2019s presence moves no position.</p>`:'',
    ].join('');
    return `<span class="mini-label">GLOBAL DISPATCH IMPACT · LOCAL MODEL · ${pair[0]} · ${d.differences.length} OF 3 POSITIONS DIFFER</span>${listLines}${lines}<p class="fine-print">${pair[1]}. Compared locally between the two modeled versions you entered \u2014 PRISM read no transaction, no protocol parameters UTxO, and no chain state, and neither version is one. Comparing is not checking or building: no dispatch was applied to either version.</p>`;
  }catch(e){return `<span class="mini-label">GLOBAL DISPATCH IMPACT · LOCAL MODEL · NOT COMPARED</span><p class="fine-print">${esc(e.message)}</p>`;}
}

function constructionExample(){
  const P1='11'.repeat(28),P2='22'.repeat(28),G='aa'.repeat(28),D='33'.repeat(28),B='cc'.repeat(28),L='ee'.repeat(28),S='dd'.repeat(28),O='99'.repeat(28);
  const NL=String.fromCharCode(10);
  return {
    action:'transfer',
    deploymentText:['global script '+G,'delegate script '+D,'base script '+B].join(NL),
    tokensText:[P1+' registered script '+L,P2+' unregistered'].join(NL),
    refsText:['registry-node-11','protocol-parameters','registry-node-cover'].join(NL),
    params:'protocol-parameters',
    registryRefsText:[P1,P2].join(NL),
    withdrawalsText:['script '+G,'script '+D,'script '+L].join(NL),
    outputsText:['script '+B+' script '+S+' '+P1,'pubkey '+O+' none -'].join(NL),
  };
}
function constructionModelInput({action='transfer',deploymentText='',tokensText='',refsText='',params='',registryRefsText='',withdrawalsText='',outputsText=''}={}){
  const NL=String.fromCharCode(10);
  const credParts=(parts,label)=>{
    if(parts.length!==2||!['script','pubkey'].includes(parts[0]))throw new Error(`Each ${label} must name a credential kind (script or pubkey) and its 28-byte hash.`);
    return {kind:parts[0],hash:parts[1]};
  };
  const deployment={};
  const depNames={global:'globalCredential',delegate:'delegateCredential',base:'base'};
  String(deploymentText??'').split(NL).map(x=>x.trim()).filter(Boolean).forEach(line=>{
    const parts=line.split(/\s+/);
    if(parts.length!==3||!(parts[0] in depNames))throw new Error(`Each deployment line must name global, delegate, or base, then a credential kind (script or pubkey) and its 28-byte hash — ${JSON.stringify(line)} given.`);
    if(deployment[depNames[parts[0]]])throw new Error(`The deployment names its ${parts[0]} credential more than once — a deployment has one of each.`);
    deployment[depNames[parts[0]]]=credParts(parts.slice(1),'deployment credential');
  });
  for(const k of ['globalCredential','delegateCredential','base'])if(!deployment[k])throw new Error(`The deployment is missing its ${k==='base'?'base':k==='globalCredential'?'global':'delegate'} credential line — the deployment names all three.`);
  const tokens=String(tokensText??'').split(NL).map(x=>x.trim()).filter(Boolean).map(line=>{
    const parts=line.split(/\s+/);
    if(parts[1]==='unregistered'&&parts.length===2)return {policy:parts[0],registered:false,logicCredential:null};
    if(parts[1]==='registered'&&parts.length===4)return {policy:parts[0],registered:true,logicCredential:credParts(parts.slice(2),'token logic credential')};
    throw new Error(`Each token line must name a policy, then registered with its logic credential kind and hash, or unregistered — ${JSON.stringify(line)} given.`);
  });
  const referenceInputs=String(refsText??'').split(NL).map(x=>x.trim()).filter(Boolean);
  const registryRefPolicies=String(registryRefsText??'').split(NL).map(x=>x.trim()).filter(Boolean);
  const withdrawals=String(withdrawalsText??'').split(NL).map(x=>x.trim()).filter(Boolean).map(line=>credParts(line.split(/\s+/),'withdrawal line'));
  const outputs=String(outputsText??'').split(NL).map(x=>x.trim()).filter(Boolean).map(line=>{
    const parts=line.split(/\s+/);
    if(parts.length<4)throw new Error(`Each output line must name a payment kind and hash, a stake kind and hash (or none and -), then any policies it carries — ${JSON.stringify(line)} given.`);
    const payment=credParts(parts.slice(0,2),'output payment credential');
    const stake=parts[2]==='none'?(parts[3]==='-'?null:(()=>{throw new Error(`An output with no stake credential names none and - — ${JSON.stringify(line)} given.`);})()):credParts(parts.slice(2,4),'output stake credential');
    return {payment,stake,policies:parts.slice(4)};
  });
  return {action,base:deployment.base,globalCredential:deployment.globalCredential,delegateCredential:deployment.delegateCredential,tokens,referenceInputs,paramsRef:String(params??'').trim(),registryRefPolicies,withdrawals,outputs};
}
function constructionPreview(input={}){
  if(!String(input.deploymentText??'').trim()&&!String(input.tokensText??'').trim())return `<p class="fine-print">Enter a modeled transaction — its declared action, the deployment credentials, the tokens it touches, its reference inputs, the policies proved by a registry reference input, its withdrawals, and its outputs — and the spec’s six construction steps are judged together as you type. The example loaded here conforms on every step.</p>`;
  try{
    const v=checkTransactionConstruction(constructionModelInput(input));
    const yn=b=>b===null?'NO VERDICT':b?'MATCHES':'FAILS';
    const short=h=>`<span class="mono">${esc(h.slice(0,8))}…</span>`;
    const head=v.valid?'TRANSACTION CONSTRUCTION · LOCAL MODEL · CONFORM':'TRANSACTION CONSTRUCTION · LOCAL MODEL · DO NOT CONFORM';
    const summary=v.valid
      ?`<p class="fine-print"><strong>The modeled construction conforms</strong> — every one of the spec’s six steps the transaction must take is present and placed as the standard requires.</p>`
      :`<p class="fine-print"><strong>The modeled construction does not conform</strong> — at least one of the six steps below is missing or misplaced, and the step names what to fix.</p>`;
    const steps=[
      `<p class="fine-print"><strong>Step 1 · Protocol parameters reference input · ${yn(v.verdicts.paramsRefIncluded)}</strong> — the parameters UTxO (<span class="mono">${esc(v.paramsRef)}</span>) ${v.verdicts.paramsRefIncluded?'is':'is not'} among the ${v.referenceInputs.length} modeled reference inputs. Steps 1 and 3 are the two the spec warns are easy to omit: neither is visible in a token’s own configuration.</p>`,
      `<p class="fine-print"><strong>Step 2 · Registry node reference inputs · ${yn(v.verdicts.registryRefsComplete)}</strong> — ${v.missingPolicies.length?`no registry node is included for ${v.missingPolicies.map(short).join(', ')}`:`every one of the ${v.tokens.length} modeled policies touched has a registry node reference input`}. Whether each proof is correct — the right node, the right covering relationship — is the proof families’ position above, not this step’s.</p>`,
      v.extraProvedPolicies.length?`<p class="fine-print"><strong>Proved policies beyond the tokens touched</strong> — ${v.extraProvedPolicies.map(short).join(', ')}: reported, never scored. The standard requires a node for each policy touched and states no prohibition on another reference input riding along.</p>`:'',
      `<p class="fine-print"><strong>Step 3 · programmableLogicGlobal withdraw-zero · ${yn(v.verdicts.globalInvoked)}</strong> — the global credential the parameters name ${v.verdicts.globalInvoked?'is':'is not'} among the modeled withdrawals, declaring the action.</p>`,
      `<p class="fine-print"><strong>Step 4 · Action delegate withdraw-zero · ${yn(v.verdicts.delegateInvoked)}</strong> — the delegate credential entered for the declared action ${v.verdicts.delegateInvoked?'is':'is not'} among the modeled withdrawals. Which credential the wiring names for the action is the dispatch panel’s position above.</p>`,
      `<p class="fine-print"><strong>Step 5 · Token logic withdraw-zero · ${yn(v.verdicts.logicInvoked)}</strong> — ${v.logicResults.filter(r=>r.registered).length?v.logicResults.filter(r=>r.registered).map(r=>`policy ${short(r.policy)}’s logic ${r.invoked?'is invoked':'is NOT invoked'}`).join('; '):'no registered token is modeled, so no token logic is required and this step carries no verdict'}. An unregistered token is treated as an ordinary native token and names no logic.</p>`,
      `<p class="fine-print"><strong>Step 6 · Programmable tokens to smart-wallet addresses only · ${yn(v.verdicts.outputsToSmartWallets)}</strong> — ${v.outputResults.filter(r=>r.carriedPolicies.length).length?v.outputResults.filter(r=>r.carriedPolicies.length).map(r=>`output ${r.index+1} ${r.toSmartWallet?'sits at a smart-wallet address (the base payment credential with a stake credential)':'does NOT sit at a smart-wallet address'}`).join('; '):'no modeled output carries a touched policy, so this step carries no verdict — the amounts outputs must hold are the output-value family’s position'}.</p>`,
      v.outputResults.some(r=>!r.carriedPolicies.length)?`<p class="fine-print"><strong>Outputs carrying no touched policy · NO VERDICT</strong> — ${v.outputResults.filter(r=>!r.carriedPolicies.length).map(r=>`output ${r.index+1}`).join(', ')}: ordinary outputs are not this step’s business and are reported, never scored.</p>`:'',
    ].join('');
    return `<span class="mini-label">${head}</span>${summary}${steps}<p class="fine-print">Judged locally against the modeled transaction entered — presence and placement only. PRISM read no transaction, no protocol parameters UTxO, and no chain state, and built nothing: proof correctness is the proof families’ position, the redeemer hints are the base family’s, output amounts are the output-value family’s, and everything the invoked delegate then validates is the delegate panels’.</p>`;
  }catch(e){return `<span class="mini-label">TRANSACTION CONSTRUCTION · LOCAL MODEL · NOT CHECKED</span><p class="fine-print">${esc(e.message)}</p>`;}
}

