function delegateModelInput({action='third-party',refs='',node='',inputs='',outputs='',start=''}={}){
  const entries=v=>String(v??'').split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{
    if(x==='base')return {atBase:true};
    if(x==='other')return {atBase:false};
    throw new Error(`Each input and output line must say base or other — ${JSON.stringify(x)} given.`);
  });
  const startRaw=String(start??'').trim();
  if(startRaw&&!/^\d+$/.test(startRaw))throw new Error(`outputs_start_idx must be a non-negative integer — ${startRaw} given, refused rather than rounded.`);
  return {
    action,
    referenceInputs:String(refs??'').split('\n').map(x=>x.trim()).filter(Boolean),
    registryNodeRef:(node??'').trim(),
    inputs:entries(inputs),
    outputs:entries(outputs),
    outputsStartIdx:startRaw===''?0:Number(startRaw),
  };
}
