function registryNodeCheckDiffPreview(input={}){
  const afterI=String(input.afterIdx??'').trim(),afterN=String(input.afterNodesText??'').trim(),afterLH=String(input.afterLogicHash??'').trim(),afterG=String(input.afterGlobalText??'').trim();
  if(!afterI&&!afterN&&!afterLH&&!afterG)return `<p class="fine-print">Enter the resolution as it would be after the change — its registry_node_idx, its modeled reference inputs, its claimed logic credential, and its global-state policies — and how the resolution checked above changes appears as you type, compared locally between the two versions. The action and the acted-on policy are the claim’s identity and are taken from the checker above.</p>`;
  try{
    const action=input.action??'unfracking',policy=input.policy??'';
    const before=registryNodeCheckModelInput({action,policy,idx:input.idx??'',nodesText:input.nodesText??'',logicKind:input.logicKind??'script',logicHash:input.logicHash??'',globalText:input.globalText??''});
    const after=registryNodeCheckModelInput({action,policy,idx:input.afterIdx??'',nodesText:input.afterNodesText??'',logicKind:input.afterLogicKind??'script',logicHash:input.afterLogicHash??'',globalText:input.afterGlobalText??''});
    const d=diffDelegateRegistryNode(before,after);
    const cred=c=>{if(c===null)return 'no node resolved';const h=c.hash?c.hash.slice(0,8)+'…':'(empty)';return `${esc(c.kind)} <span class="mono">${esc(h)}</span>`;};
    const short=h=>`<span class="mono">${esc(h.slice(0,8))}…</span>`;
    const labels={'unchanged':['REGISTRY-NODE RESOLUTION UNCHANGED','the change leaves the resolution exactly as checked above — the same node resolves, it carries the policy, or not, and the credential it names is the one claimed, or not, in both versions'],'became-not-conforming':['BECAME NOT CONFORMING','the after version no longer satisfies a position it satisfied before — the hint no longer resolves to the node carrying the policy, or that node no longer names the claimed credential, or a global state it names is no longer carried — so the delegate would refuse an action the before version allowed'],'became-conforming':['BECAME CONFORMING','the before version broke a position and the after version satisfies them all — the hint resolves to the node carrying the policy, that node names the claimed credential, and any global state it names is carried'],'still-not-conforming':['STILL NOT CONFORMING — DIFFERENTLY','neither version conforms, but a position changed underneath it, so fixing the before version’s failure does not fix the after version’s'],'requirement-changed':['REQUIREMENT CHANGED','the resolution conforms on both sides, but the node logic credential moved — the credential the resolved node requires the action to invoke is a different credential, and the resolution survives, proving a different configuration']};
    const pair=labels[d.change];
    const showVal=(field,v)=>field==='status'?(v==='conforming'?'conforming':'not conforming'):v===null?'no verdict':v?'MATCHES':'FAILS';
    const lines=d.differences.map(x=>`<p class="fine-print"><strong>${esc(x.label)} · DIFFERS</strong> — before: ${x.field==='nodeLogicCredential'?cred(x.before):esc(showVal(x.field,x.before))}; after: ${x.field==='nodeLogicCredential'?cred(x.after):esc(showVal(x.field,x.after))}.</p>`).join('');
    const listLines=[
      d.registryNodeIdxChanged?`<p class="fine-print"><strong>registry_node_idx changed</strong> — before: ${d.before.registryNodeIdx}; after: ${d.after.registryNodeIdx}. Reported, never counted: the index is a hint, and the same node reached at a new index resolves identically.</p>`:'',
      d.claimedLogicCredentialChanged?`<p class="fine-print"><strong>Claimed logic credential changed</strong> — before: ${cred(d.before.logicCredential)}; after: ${cred(d.after.logicCredential)}. Reported, never counted: its only scored consequence is the logic credential agreement position above, so counting it would count one fact twice.</p>`:'',
      d.changedNodeIndices.length?`<p class="fine-print"><strong>Reference inputs changed</strong> — input ${d.changedNodeIndices.map(i=>i+1).join(', input ')}. Reported, never counted: a node the resolution never reaches moves no position, and where a node’s change does move one, that position already counts it.</p>`:'',
      (d.addedNodeCount||d.removedNodeCount)?`<p class="fine-print"><strong>Reference inputs ${d.addedNodeCount?'added '+d.addedNodeCount:''}${d.addedNodeCount&&d.removedNodeCount?', ':''}${d.removedNodeCount?'removed '+d.removedNodeCount:''}</strong> — ${d.nodeCountBefore} modeled before, ${d.nodeCountAfter} after. Reported, never counted, for the same reason.</p>`:'',
      d.addedGlobalStatePolicies.length?`<p class="fine-print"><strong>Global-state policies added</strong> — ${d.addedGlobalStatePolicies.map(short).join(', ')}.</p>`:'',
      d.removedGlobalStatePolicies.length?`<p class="fine-print"><strong>Global-state policies removed</strong> — ${d.removedGlobalStatePolicies.map(short).join(', ')}.</p>`:'',
      d.globalStateModeChanged?`<p class="fine-print"><strong>Global-state mode changed</strong> — before: ${esc(d.globalStateModeBefore??'no verdict')}; after: ${esc(d.globalStateModeAfter??'no verdict')}. Reported, never counted: it is the breakdown behind the global-state reference position above.</p>`:'',
    ].join('');
    return `<span class="mini-label">DELEGATE REGISTRY-NODE IMPACT · LOCAL MODEL · ${pair[0]} · ${d.differences.length} OF 6 POSITIONS DIFFER</span>${listLines}${lines}<p class="fine-print">${pair[1]}. Compared locally between the two modeled versions you entered — PRISM read no transaction, no registry, and no UTxO, and neither version is one. Comparing is not checking or building: no resolution was applied to either version. Whether the reference input at that index in a real transaction really holds either version’s node is a fact about a real registry this model does not read, on both sides alike.</p>`;
  }catch(e){return `<span class="mini-label">DELEGATE REGISTRY-NODE IMPACT · LOCAL MODEL · NOT COMPARED</span><p class="fine-print">${esc(e.message)}</p>`;}
}

function transferAuthExample(){
  const A='aa'.repeat(28),B='bb'.repeat(28),C='cc'.repeat(28),D='dd'.repeat(28),E='ee'.repeat(28);
  return {spentText:`pubkey ${A}\nscript ${B}`,tokensText:`registered ${C} script ${E}\nunregistered ${D}`,withdrawalsText:`script ${E}\nscript ${B}`,signersText:A};
}
function transferAuthModelInput({spentText='',tokensText='',withdrawalsText='',signersText=''}={}){
  const creds=(text,label)=>String(text??'').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{
    const bits=line.split(/\s+/).filter(Boolean);
    if(bits.length!==2||!['script','pubkey'].includes(bits[0]))throw new Error(`Each ${label} line must name a kind (script or pubkey) and a 28-byte hash — ${JSON.stringify(line)} given.`);
    return {kind:bits[0],hash:bits[1]};
  });
  const tokens=String(tokensText??'').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{
    const parts=line.split(/\s+/);
    if((parts.length!==2&&parts.length!==4)||!['registered','unregistered'].includes(parts[0]))throw new Error(`Each token line must name registered or unregistered and the policy, and — in four parts — a transfer credential kind and hash — ${JSON.stringify(line)} given.`);
    if(parts[0]==='registered'&&parts.length!==4)throw new Error(`A registered token line must name its transfer credential kind and hash — ${JSON.stringify(line)} given.`);
    if(parts.length===4&&!['script','pubkey'].includes(parts[2]))throw new Error(`A token line's transfer credential kind must be script or pubkey — ${JSON.stringify(line)} given.`);
    return {policy:parts[1],registered:parts[0]==='registered',transferCredential:parts.length===4?{kind:parts[2],hash:parts[3]}:null};
  });
  return {spentStakeCredentials:creds(spentText,'spent stake credential'),tokens,withdrawals:creds(withdrawalsText,'withdrawal'),signers:String(signersText??'').split('\n').map(x=>x.trim()).filter(Boolean)};
}
function transferAuthPreview(input={}){
  if(!String(input.spentText??'').trim()&&!String(input.tokensText??'').trim()&&!String(input.withdrawalsText??'').trim()&&!String(input.signersText??'').trim())return `<p class="fine-print">Enter a claimed transfer — the stake credential of each UTxO spent from a programmableLogicBase address, the policies its registry proofs proved registered or not (with each registered token's transfer_logic_script), the transaction's withdrawals, and its signers — and the transfer delegate's authorization and logic-execution requirements are judged as you type. The example loaded here conforms.</p>`;
  try{
    const v=checkTransferAuthorization(transferAuthModelInput(input));
    const yn=b=>b?'MATCHES':'FAILS';
    const inputLines=v.spentInputs.map(r=>r.mode==='signature'
      ?`<p class="fine-print"><strong>Spent UTxO ${r.index+1} authorization · ${yn(r.authorized)}</strong> — its stake credential is a public key, so it authorises by signature: its key ${r.authorized?'is':'is not'} among the modeled signers.</p>`
      :`<p class="fine-print"><strong>Spent UTxO ${r.index+1} authorization · ${yn(r.authorized)}</strong> — its stake credential is a script, so it authorises by execution: that script ${r.authorized?'appears':'does not appear'} among the modeled withdrawals.</p>`).join('');
    const tokenLines=v.tokens.map(t=>{
      const short=`<span class="mono">${esc(t.policy.slice(0,8))}&#8230;</span>`;
      if(!t.registered)return `<p class="fine-print"><strong>Policy ${short} transfer logic · NO VERDICT</strong> — proven not registered, so it is treated as an ordinary native token and can be transferred without additional validation; no execution is required of it.</p>`;
      if(t.mode==='none')return `<p class="fine-print"><strong>Policy ${short} transfer logic · FAILS</strong> — its transfer_logic_script names no script or key (empty hash), so it can appear in no withdrawal map and nothing was executed for this token.</p>`;
      return `<p class="fine-print"><strong>Policy ${short} transfer logic · ${yn(t.executed)}</strong> — its ${esc(t.mode)} transfer credential ${t.executed?'appears':'does not appear'} among the ${v.withdrawals.length} modeled withdrawal${v.withdrawals.length===1?'':'s'}; the delegate requires that credential&#8217;s withdraw-zero in the transaction.</p>`;
    }).join('');
    const logicLine=v.verdicts.logicExecution===null?`<p class="fine-print"><strong>Transfer logic execution · NO VERDICT</strong> — no registered policy is modeled, so there is no transfer logic the delegate requires executed.</p>`:'';
    const head=v.valid?'TRANSFER AUTHORIZATION · LOCAL MODEL · CONFORM':'TRANSFER AUTHORIZATION · LOCAL MODEL · DO NOT CONFORM';
    const summary=v.valid
      ?`<p class="fine-print"><strong>The claimed transfer conforms on authorization and execution</strong> — every spent base UTxO is authorised by its own stake credential${v.registeredCount?', and every registered token&#8217;s transfer logic was invoked via withdraw-zero':''}.</p>`
      :`<p class="fine-print"><strong>The claimed transfer breaks the positions marked FAILS</strong> — carried into a transaction as claimed, the transfer delegate would refuse it there.</p>`;
    return `<span class="mini-label">${head}</span>${summary}${inputLines}${logicLine}${tokenLines}<p class="fine-print">Judged locally against the modeled stake credentials, tokens, withdrawals, and signers entered. PRISM read no transaction, no registry, and no UTxO: whether the registry proofs that mark a policy registered actually validate, and whether a policy&#8217;s RegistryNode actually carries the transfer credential entered here, are judged by the registry-proof checker below, and whether a listed withdrawal really executed and a listed signer really signed are facts about a real transaction, not judged here. The expected output value is the calculator below.</p>`;
  }catch(e){return `<span class="mini-label">TRANSFER AUTHORIZATION · LOCAL MODEL · NOT CHECKED</span><p class="fine-print">${esc(e.message)}</p>`;}
}

