    const pair=labels[d.change];
    const showVal=(field,v)=>field==='status'?(v==='conforming'?'conforming':'not conforming'):field==='holderAuthorization'?(v===null?'no verdict':v?'authorised':'not authorised'):field==='logicExecution'?(v===null?'no verdict':v?'executed':'not executed'):null;
