function transferProofDiffPreview(input={}){
  const afterP=String(input.afterProofsText??'').trim(),afterN=String(input.afterNodesText??'').trim(),afterG=String(input.afterGlobalText??'').trim();
  if(!afterP&&!afterN&&!afterG)return `<p class="fine-print">Enter the transfer’s proofs as they would be after the change — its registry proofs, its reference inputs, and its global-state NFT policies — and how the resolution checked above changes appears as you type, compared locally between the two versions.</p>`;
  try{
    const before=transferProofModelInput({proofsText:input.proofsText??'',nodesText:input.nodesText??'',globalText:input.globalText??''});
    const after=transferProofModelInput({proofsText:input.afterProofsText??'',nodesText:input.afterNodesText??'',globalText:input.afterGlobalText??''});
    const d=diffTransferRegistryProofs(before,after);
    const short=h=>`<span class="mono">${esc(h.slice(0,8))}…</span>`;
    const credStr=c=>c===null?'no credential':`${esc(c.kind)} <span class="mono">${esc(c.hash?c.hash.slice(0,8)+'…':'(empty)')}</span>`;
    const req=v=>v.length?v.map(e=>e.proofType==='TokenExists'
      ?`${short(e.policy)} exists → node key ${e.key===null?'no node':short(e.key)}, transfer ${e.transfer===null?'no node':credStr(e.transfer)}, global state ${e.globalStateCs===null?'no node':e.globalStateCs===''?'none':short(e.globalStateCs)}`
      :`${short(e.policy)} notexists → covering key ${e.key===null?'no node':e.key===''?'origin':short(e.key)}, next ${e.next===null?'no node':e.next===''?'none':short(e.next)}`).join('; '):'(none)';
    const labels={'unchanged':['TRANSFER REGISTRY PROOFS UNCHANGED','the change leaves the resolution exactly as checked above — every hint resolves to the node it must name, each registered token’s node carries the claimed transfer credential, and every global state a matched node names is referenced, or not, in both versions'],'became-not-conforming':['BECAME NOT CONFORMING','the after version no longer satisfies a position it satisfied before — a hint resolves to no node, a proof no longer matches its node, a node’s transfer_logic_script is no longer the claimed credential, or a named global state is no longer referenced — so the transfer delegate would refuse a transfer the before version allowed'],'became-conforming':['BECAME CONFORMING','the before version broke a position and the after version satisfies them all — every hint resolves, each proof matches its node, the claimed credentials agree, and every named global state is referenced'],'still-not-conforming':['STILL NOT CONFORMING — DIFFERENTLY','neither version conforms, but a position changed underneath it, so fixing the before version’s failure does not fix the after version’s'],'requirement-changed':['REQUIREMENT CHANGED','the resolution conforms on both sides, but the resolved node requirements moved — the configuration the modeled registry demands of these proofs is a different configuration, and the resolution survives, proving the same policies against a different registry']};
    const pair=labels[d.change];
    const showVal=(field,v)=>field==='status'?(v==='conforming'?'conforming':'not conforming'):field==='nodesResolve'?(v?'every proof resolves':'a proof resolves to no node'):field==='proofsMatchNodes'?(v?'every proof matches its node':'a proof does not match its node'):field==='transferCredentialMatches'?(v===null?'no verdict':v?'the claimed credentials agree':'a claimed credential disagrees'):field==='globalStateReference'?(v===null?'no verdict':v?'every named global state is referenced':'a named global state is not referenced'):null;
    const lines=d.differences.map(x=>x.field==='resolvedRequirements'
      ?`<p class="fine-print"><strong>${esc(x.label)} · DIFFERS</strong> — before: ${req(x.before)}; after: ${req(x.after)}.</p>`
      :`<p class="fine-print"><strong>${esc(x.label)} · DIFFERS</strong> — before: ${esc(showVal(x.field,x.before))}; after: ${esc(showVal(x.field,x.after))}.</p>`).join('');
    const listLines=[
      d.proofsAdded.length?`<p class="fine-print"><strong>Proofs added</strong> — ${d.proofsAdded.map(short).join(', ')} (${d.existsCountBefore} exists and ${d.notExistsCountBefore} not-exists before, ${d.existsCountAfter} and ${d.notExistsCountAfter} after). Reported, never counted: a proof joining or leaving moves a position only through the requirement it names and the verdicts that requirement carries.</p>`:'',
      d.proofsRemoved.length?`<p class="fine-print"><strong>Proofs removed</strong> — ${d.proofsRemoved.map(short).join(', ')} (${d.existsCountBefore} exists and ${d.notExistsCountBefore} not-exists before, ${d.existsCountAfter} and ${d.notExistsCountAfter} after). Reported, never counted, for the same reason.</p>`:'',
      d.nodeIdxChanges.length?`<p class="fine-print"><strong>Node indexes changed</strong> — ${d.nodeIdxChanges.map(c=>`${short(c.policy)} ${c.before} → ${c.after}`).join(', ')}. Reported, never counted: the index is a hint — the same node at a new index resolves identically.</p>`:'',
      d.claimedCredentialChanges.length?`<p class="fine-print"><strong>Claimed credentials changed</strong> — ${d.claimedCredentialChanges.map(short).join(', ')}. Reported, never counted: for an exists proof its scored consequence is the agreement position above, and a not-exists proof’s entered credential is given no verdict at all.</p>`:'',
      d.changedNodeIndices.length?`<p class="fine-print"><strong>Reference inputs changed</strong> — at index ${d.changedNodeIndices.join(', ')} (${d.referenceCountBefore} modeled before, ${d.referenceCountAfter} after). Reported, never counted: they are the causes, the verdict positions above are the consequence.</p>`:'',
      d.globalStatePoliciesAdded.length?`<p class="fine-print"><strong>Global-state policies added</strong> — ${d.globalStatePoliciesAdded.map(short).join(', ')}. Reported, never counted, for the same reason.</p>`:'',
      d.globalStatePoliciesRemoved.length?`<p class="fine-print"><strong>Global-state policies removed</strong> — ${d.globalStatePoliciesRemoved.map(short).join(', ')}. Reported, never counted, for the same reason.</p>`:'',
    ].join('');
    return `<span class="mini-label">TRANSFER REGISTRY-PROOF IMPACT · LOCAL MODEL · ${pair[0]} · ${d.differences.length} OF 6 POSITIONS DIFFER</span>${listLines}${lines}<p class="fine-print">${pair[1]}. Compared locally between the two modeled versions you entered — PRISM read no transaction, no registry, and no UTxO, and neither version is one. Comparing is not checking or building: no proof was resolved against a real registry. Whether the proof list is complete and in lexicographic order is the proof-list checker’s position above, on both sides alike, and whether a matched node’s credential was executed is the authorization checker’s.</p>`;
  }catch(e){return `<span class="mini-label">TRANSFER REGISTRY-PROOF IMPACT · LOCAL MODEL · NOT COMPARED</span><p class="fine-print">${esc(e.message)}</p>`;}
}
