      const fields=p.changedFields.length?` Changed positions: ${p.changedFields.join(', ')}.`:'';
      return `<p class="fine-print"><strong>Policy <span class="mono">${esc(p.policy)}</span> · ${pair[0]}</strong> — before: ${esc(describe(p.before))}; after: ${esc(describe(p.after))}.${fields} ${pair[1]}.</p>`;
