document.addEventListener('change',async event=>{
  const el=event.target;
  if(el.id==='network-select'){state.network=el.value;state.wallet=null;state.midnight=null;state.asset=null;state.reference=null;state.tip=null;state.requestId++;save();updateWalletButton();render();refreshTip();toast(`Switched to ${NETWORKS[state.network].name}. Reconnect wallets for this network.`);}
  if(el.id==='import-preview-file'&&el.files[0]){try{if(el.files[0].size>100000)throw new Error('Choose a file smaller than 100 KB.');const verified=parseRegistryDatumPreview(await el.files[0].text());toast(`Preview verified for ${verified.token.ticker}: application-specific, not a CIP datum, nothing registered on chain.`);}catch(e){toast(`Preview check failed: ${e.message}`,true);}el.value='';}
  if(el.id==='compare-preview-file'&&el.files[0]){try{if(el.files[0].size>100000)throw new Error('Choose a file smaller than 100 KB.');const diff=diffRegistryDatumPreview(await el.files[0].text(),state.design,state.network);const box=$('#registry-compare-result');if(box)box.innerHTML=registryComparePreview(diff);toast(diff.same?`Preview file matches your current design — all ${diff.compared} fields agree.`:`Preview file differs in ${diff.differences.length} of ${diff.compared} fields — your current design was not changed.`);}catch(e){const box=$('#registry-compare-result');if(box)box.innerHTML=`<div class="validation" role="alert">Preview comparison refused: ${esc(e.message)} A file that fails any check is refused whole — it is never partially compared, and your current design was not changed.</div>`;toast(`Preview comparison failed: ${e.message}`,true);}el.value='';}
  if(el.id==='compare-design-file'&&el.files[0]){try{if(el.files[0].size>100000)throw new Error('Choose a file smaller than 100 KB.');const diff=diffDesignFile(await el.files[0].text(),state.design,state.network);const box=$('#design-compare-result');if(box)box.innerHTML=designComparePreview(diff);toast(diff.same?`Design file matches your current design — all ${diff.compared} fields agree.`:`Design file differs in ${diff.differences.length} of ${diff.compared} fields — your current design was not changed.`);}catch(e){const box=$('#design-compare-result');if(box)box.innerHTML=`<div class="validation" role="alert">Design comparison refused: ${esc(e.message)} A file that fails any check is refused whole — it is never partially compared, and your current design was not changed.</div>`;toast(`Design comparison failed: ${e.message}`,true);}el.value='';}
  if(el.id==='verify-design-file'&&el.files[0]){try{if(el.files[0].size>100000)throw new Error('Choose a file smaller than 100 KB.');const verified=verifyManifest(await el.files[0].text());const box=$('#design-verify-result');if(box)box.innerHTML=designVerifyPreview(verified);toast(`Design file verified for ${verified.summary.ticker} — your current design was not changed.`);}catch(e){const box=$('#design-verify-result');if(box)box.innerHTML=`<div class="validation" role="alert">Design file refused: ${esc(e.message)} A file that fails any check is refused whole — it is never partially verified, and your current design was not changed.</div>`;toast(`Design check failed: ${e.message}`,true);}el.value='';}
  if(el.id==='import-file'&&el.files[0]){try{if(el.files[0].size>100000)throw new Error('Choose a file smaller than 100 KB.');const loaded=parseManifest(await el.files[0].text());state.design=loaded.design;if(state.network!==loaded.network){state.wallet=null;state.midnight=null;state.network=loaded.network;state.tip=null;state.requestId++;$('#network-select').value=state.network;updateWalletButton();refreshTip();}state.simulation=null;state.seqResult=null;state.supplyResult=null;state.supplySeqResult=null;state.timelineResult=null;state.subPreset=null;state.subResult=null;state.seizureResult=null;state.denylistResult=null;state.kycSeqResult=null;state.basicKycResult=null;state.seqMode='preset';state.seqCustom=null;state.tab='design';state.supplySeqMode='preset';state.supplySeqCustom=null;state.timelineMode='preset';state.timelineCustom=null;state.denylistMode='preset';state.denylistCustom=null;state.kycSeqMode='preset';state.kycSeqCustom=null;state.basicKycMode='preset';state.basicKycCustom=null;state.subMode='preset';state.subCustom=null;state.seizureMode='preset';state.seizureCustom=null;save();if(location.hash!=='#studio')location.hash='studio';else render();toast('Design imported successfully.');}catch(e){toast(`Import failed: ${e.message}`,true);}el.value='';}
});
